export function escapeHTML(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
export function filterIncidents(items,query='',severity='all'){const q=query.trim().toLowerCase();return items.filter(i=>(severity==='all'||i.severity===severity)&&[i.rule,i.actor,i.tenant,i.status,i.id].some(v=>String(v).toLowerCase().includes(q)));}
export function posture(assets){const findings=[];for(const a of assets){if(a.public)findings.push({asset:a.id,rule:'POSTURE-001',severity:'high',reason:'Public exposure in supplied configuration'});if((a.permissions||[]).includes('*'))findings.push({asset:a.id,rule:'POSTURE-002',severity:'high',reason:'Wildcard permissions'});if(a.encrypted===false)findings.push({asset:a.id,rule:'POSTURE-003',severity:'medium',reason:'Encryption disabled'});}return findings;}
export function paths(assets){const by=new Map(assets.map(a=>[a.id,a])),out=[];function visit(id,chain){if(chain.includes(id)||!by.has(id))return;const a=by.get(id),next=[...chain,id];if(a.sensitive)out.push(['internet',...next]);for(const target of a.can_access||[])visit(target,next);}for(const a of assets)if(a.public)visit(a.id,[]);return out;}
export function brief(incident,events){const evidence=events.filter(e=>incident.evidence_ids.includes(e.id));return {text:`Rule ${incident.rule} observed ${evidence.length} matching events for ${incident.actor} in ${incident.tenant}. Severity is ${incident.severity}. ${incident.guidance}`,references:evidence.map(e=>e.id),label:'Deterministic evidence summary; no model or command execution'};}
